          "component": "Column",
          "children": [
            "assumptions-header",
            "assumptions-list"
          ]
        },
        {
          "id": "assumptions-header",
          "component": "Text",
          "variant": "h3",
          "text": "Assumptions"
        },
        {
          "id": "assumptions-list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "assumption-1",
            "assumption-2",
            "assumption-3",
            "assumption-4"
          ]
        },
        {
          "id": "assumption-1",
          "component": "Text",
          "text": "This itinerary assumes your family will utilize Tokyo's efficient public transportation system (trains and subways)."
        },
        {
          "id": "assumption-2",
          "component": "Text",
          "text": "Daily cost estimates exclude international airfare and accommodation, focusing on local transportation, meals, and activities."
        },
        {
          "id": "assumption-3",
          "component": "Text",
          "text": "Specific attraction opening hours and exact prices should be verified closer to your travel date."
        },
        {
          "id": "assumption-4",
          "component": "Text",
          "text": "Ghibli Museum tickets require advance booking, often months ahead."
        },
        {
          "id": "divider-1",
          "component": "Divider"
        },
        {
