        {
          "id": "day-1-title",
          "component": "Text",
          "variant": "h3",
          "text": "Day 1: Arrival & Shinjuku - City Views and Green Spaces"
        },
        {
          "id": "day-1-meta",
          "component": "Text",
          "variant": "caption",
          "text": "Date: 2025-06-10 (Tuesday) | Neighborhood: Shinjuku | Theme: Cityscapes, Relaxed Exploration, Modern Tokyo"
        },
        {
          "id": "day-1-activities-header",
          "component": "Text",
          "variant": "h4",
          "text": "Activities"
        },
        {
          "id": "day-1-activities",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day-1-act-1",
            "day-1-act-2",
            "day-1-act-3"
          ]
        },
        {
          "id": "day-1-act-1",
          "component": "Text",
          "text": "Morning/Afternoon: Arrive at Narita (NRT) or Haneda (HND) Airport, transfer to your hotel, check-in, and settle."
        },
        {
          "id": "day-1-act-2",
          "component": "Text",
          "text": "Afternoon: Visit Shinjuku Gyoen National Garden. A beautiful oasis perfect for unwinding after travel."
        },
        {
          "id": "day-1-act-3",
          "component": "Text",
          "text": "Evening: Ascend to the Tokyo Metropolitan Government Building Observation Decks for free panoramic city views. Explore Shinjuku's bustling streets and enjoy dinner."
        },
        {
          "id": "day-1-attractions-header",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day-1-attractions",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day-1-attr-1",
            "day-1-attr-2"
          ]
        },
        {
          "id": "day-1-attr-1",
          "component": "Text",
          "text": "Shinjuku Gyoen National Garden: A large park with traditional Japanese, French, and English landscape gardens."
        },
        {
          "id": "day-1-attr-2",
          "component": "Text",
          "text": "Tokyo Metropolitan Government Building: Free observation decks offering stunning views of Tokyo, including Mount Fuji on clear days."
        },
        {
          "id": "day-1-cost",
          "component": "Text",
          "variant": "body",
          "text": "Estimated Cost (Family of 4): USD 320 (Transport: $50, Meals: $200, Activities: $70)"
        },
