            "day-2-attractions",
            "day-2-cost"
          ]
        },
        {
          "id": "day-2-title",
          "component": "Text",
          "variant": "h3",
          "text": "Day 2: Mitaka & Shibuya - Ghibli Magic and Iconic Crossing"
        },
        {
          "id": "day-2-meta",
          "component": "Text",
          "variant": "caption",
          "text": "Date: 2025-06-11 (Wednesday) | Neighborhood: Mitaka, Shibuya | Theme: Anime Immersion, Pop Culture Icon"
        },
        {
          "id": "day-2-img-ghibli",
          "component": "Image",
          "url": "/assets/ghibli_museum.jpg",
          "variant": "largeFeature",
          "fit": "cover"
        },
        {
          "id": "day-2-activities-header",
          "component": "Text",
          "variant": "h4",
          "text": "Activities"
        },
        {
          "id": "day-2-activities",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day-2-act-1",
            "day-2-act-2",
            "day-2-act-3"
          ]
        },
        {
          "id": "day-2-act-1",
          "component": "Text",
          "text": "Morning: Journey to Mitaka for a pre-booked visit to the Ghibli Museum. Immerse yourselves in the enchanting world of Studio Ghibli."
        },
        {
          "id": "day-2-act-2",
          "component": "Text",
          "text": "Afternoon: Explore Inokashira Park, adjacent to the museum, which features a zoo and boating pond. Travel to Shibuya."
        },
        {
          "id": "day-2-act-3",
          "component": "Text",
          "text": "Evening: Experience the famous Shibuya Crossing, visit the Hachiko statue, and explore Shibuya's shops and restaurants."
        },
        {
          "id": "day-2-img-shibuya",
          "component": "Image",
          "url": "/assets/shibuya_crossing.jpg",
          "variant": "mediumFeature",
          "fit": "cover"
        },
        {
          "id": "day-2-attractions-header",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day-2-attractions",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day-2-attr-1",
            "day-2-attr-2",
            "day-2-attr-3"
          ]
        },
        {
          "id": "day-2-attr-1",
          "component": "Text",
          "text": "Ghibli Museum (Mitaka): A whimsical museum dedicated to the works of Studio Ghibli. IMPORTANT: Tickets must be purchased months in advance."
        },
        {
          "id": "day-2-attr-2",
          "component": "Text",
          "text": "Inokashira Park: A large, family-friendly park with a zoo, an aquarium, and paddle boats."
        },
        {
          "id": "day-2-attr-3",
          "component": "Text",
          "text": "Shibuya Crossing: One of the world's busiest intersections, an iconic Tokyo experience."
        },
        {
          "id": "day-2-cost",
          "component": "Text",
          "variant": "body",
          "text": "Estimated Cost (Family of 4): USD 360 (Transport: $60, Meals: $220, Activities: $80)"
        },
        {
