          ]
        },
        {
          "id": "day-4-act-1",
          "component": "Text",
          "text": "Full Day: Take the Yurikamome line to Odaiba, a futuristic entertainment hub."
        },
        {
          "id": "day-4-act-2",
          "component": "Text",
          "text": "Morning: Visit Miraikan (National Museum of Emerging Science and Innovation) for hands-on exhibits on robotics, space, and technology."
        },
        {
          "id": "day-4-act-3",
          "component": "Text",
          "text": "Afternoon: Experience teamLab Planets TOKYO, an immersive digital art museum (reserve tickets in advance). See the life-sized Gundam statue at DiverCity Tokyo Plaza."
        },
        {
          "id": "day-4-act-4",
          "component": "Text",
          "text": "Evening: Enjoy dinner with bay views and perhaps a ride on the Daikanransha Ferris Wheel."
        },
        {
          "id": "day-4-attractions-header",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day-4-attractions",
          "component": "List",
          "direction": "vertical",
          "children": [
            "day-4-attr-1",
            "day-4-attr-2",
            "day-4-attr-3"
          ]
        },
        {
          "id": "day-4-attr-1",
          "component": "Text",
          "text": "Miraikan (National Museum of Emerging Science and Innovation): Interactive exhibits on cutting-edge science and technology, including ASIMO robot demonstrations."
        },
        {
          "id": "day-4-attr-2",
          "component": "Text",
          "text": "teamLab Planets TOKYO: A highly immersive digital art experience that engages all senses."
        },
        {
          "id": "day-4-attr-3",
          "component": "Text",
          "text": "Gundam Base Tokyo (DiverCity Tokyo Plaza): See the impressive life-sized Gundam statue and explore the official shop."
        },
        {
          "id": "day-4-cost",
          "component": "Text",
          "variant": "body",
          "text": "Estimated Cost (Family of 4): USD 420 (Transport: $60, Meals: $240, Activities: $120)"
        },
